  `,"basic.src.services.NeighborsQuery.ExportInterfaceGigraphdataNodesNode":`
  export interface GIGraphData {
    nodes: {
      // 节点ID
      id: string;
      // 节点类型的枚举值。Property Graph 也称之为 node.label
      nodeType: string;
      // 业务数据,注意需要打平,暂不支持嵌套
      data: {};
      // 业务数据（data）中的哪个字段，用来映射节点类型
      nodeTypeKeyFromProperties?: string;
    }[];
    edges: {
      // 边ID
      id: string;
      // 边关联的 source 节点ID
      source: string;
      // 边关联的 target 节点ID
      target: string;
      // 边类型的枚举值。Property Graph 也称之为 edge.label
      edgeType: string;
      // 业务数据,注意需要打平,暂不支持嵌套
      data: {};
      // 业务数据（data）中的哪个字段，用来映射边类型
      edgeTypeKeyFromProperties?: string;
    }[];
  }
